/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherit = require( '@stdlib/utils/inherit' );
var lil = require( './../globals/lil_gui.js' );
var config = require( './../config.js' );
var log = require( './../log.js' );
var createGeneral = require( './menus/general.js' );
var createPadding = require( './menus/padding.js' );
var createTitle = require( './menus/title.js' );
var createAxes = require( './menus/axes.js' );
var sync = require( './config/sync.js' );
var onChange = require( './on_change.js' );
var defaults = require( './defaults.js' );


// MAIN //

/**
* Constructor for an editor manager.
*
* @private
* @constructor
* @param {Object} state - state object
* @returns {Editor} editor instance
*/
function Editor( state ) {
	if ( !( this instanceof Editor ) ) {
		return new Editor( state );
	}
	EventEmitter.call( this );

	// Bound state object:
	this._state = state;

	// GUI instance:
	this._editor = null;

	// Editor toggle state:
	this._toggle = false;

	// Controller configurations:
	this._config = {
		'general': {
			'renderer': 'svg'
		},
		'axes': [],
		'legends': [],
		'marks': [],
		'padding': {},
		'projections': [],
		'scales': [],
		'title': {}
	};

	// Editor tree:
	this._tree = null;
	this._initTree();

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Editor, EventEmitter );

/**
* Callback upon editor change events.
*
* @private
* @name _onChange
* @memberof Editor.prototype
* @type {Function}
* @param {Object} event - event object
*/
setReadOnly( Editor.prototype, '_onChange', onChange );

/**
* Initializes an editor tree.
*
* @private
* @name _initTree
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, '_initTree', function initTree() {
	this._tree = {
		'general': null,
		'axes': null,
		'legends': null,
		'marks': null,
		'padding': null,
		'projections': null,
		'scales': null,
		'title': null
	};
	return this;
});

/**
* Creates an editor.
*
* @name create
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'create', function create() {
	var editor;
	var conf;
	var self;
	var o;

	self = this;

	editor = new lil.GUI({
		'width': config.editor.width
	});

	editor.title( 'Editor' );
	editor.close();

	o = {
		'Toggle Menus': toggleFolders
	};
	editor.add( o, 'Toggle Menus' );

	conf = this._config;
	this._tree.general = createGeneral( editor, conf.general );
	this._tree.padding = createPadding( editor, conf.padding );
	this._tree.title = createTitle( editor, conf.title );
	this._tree.axes = createAxes( editor, conf.axes, this._state.schema.raw );

	editor.onFinishChange( onChange );

	this._editor = editor;
	return this;

	/**
	* Toggles editor folders.
	*
	* @private
	*/
	function toggleFolders() {
		self.toggleFolders();
	}

	/**
	* Callback invoked upon an editor change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		self._onChange( event ); // eslint-disable-line no-underscore-dangle
	}
});

/**
* Editor configuration defaults.
*
* @name defaults
* @memberof Editor.prototype
* @type {Object}
* @default {...}
*/
setReadOnly( Editor.prototype, 'defaults', defaults );

/**
* Initializes an editor.
*
* @name init
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'init', function init() {
	if ( this._editor ) {
		// If there is an existing editor, go ahead and remove it...
		this.remove();
	}
	log( 'Initializing editor...' );
	sync( this._config, this._state.schema.raw );
	this.create();
	log( 'Editor initialized.' );
	return this;
});

/**
* Refreshes an editor.
*
* @name refresh
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'refresh', function refresh() {
	log( 'Refreshing editor...' );
	sync( this._config, this._state.schema.raw );
	this.refreshControllers();
	log( 'Editor refreshed.' );
	return this;
});

/**
* Refreshes editor controllers.
*
* @name refreshControllers
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'refreshControllers', function refreshControllers() {
	var controllers;
	var i;

	log( 'Refreshing editor controllers...' );
	controllers = this._editor.controllersRecursive();
	for ( i = 0; i < controllers.length; i++ ) {
		controllers[ i ].updateDisplay();
	}
	log( 'Successfully refreshed editor controllers.' );
	return this;
});

/**
* Removes an editor.
*
* @name remove
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'remove', function remove() {
	log( 'Removing editor...' );
	this._editor.destroy();
	this._initTree();
	log( 'Editor removed.' );
	return this;
});

/**
* Toggles editor folders.
*
* @name toggleFolders
* @memberof Editor.prototype
* @type {Function}
* @returns {Editor} editor instance
*/
setReadOnly( Editor.prototype, 'toggleFolders', function toggleFolders() {
	var folders;
	var method;
	var editor;
	var flg;
	var i;

	editor = this._editor;
	if ( !editor ) {
		return;
	}
	log( 'Toggling editor folders...' );

	flg = this._toggle;
	method = ( flg ) ? 'close' : 'open';

	folders = editor.foldersRecursive();
	for ( i = 0; i < folders.length; i++ ) {
		folders[ i ][ method ]();
	}
	this._toggle = !flg;
	log( 'Toggled editor folders.' );

	return this;
});


// EXPORTS //

module.exports = Editor;
